const MAX_DESC = 8000;
const TRACKING = ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','ref','fbclid','gclid'];

function htmlToText(input) {
  const decode = (t) => t
    .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
    .replace(/&nbsp;/gi, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
    .replace(/&amp;/gi, '&');

  let s = String(input ?? '');
  s = decode(s);                                        
  s = s.replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ');
  s = s.replace(/<\/(p|div|li|h[1-6]|tr)>|<br\s*\/?>/gi, '\n');
  s = s.replace(/<[^>]+>/g, ' ');                      
  s = decode(s);                                       
  s = s.replace(/<[^>]+>/g, ' ');                      
  return s.replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
}

function cleanUrl(u) {
  let s = String(u || '').trim().split('#')[0];
  const q = s.indexOf('?');
  if (q === -1) return s;
  const base = s.slice(0, q);
  const kept = s.slice(q + 1).split('&').filter(function (p) {
    return p && TRACKING.indexOf(p.split('=')[0].toLowerCase()) === -1;
  });
  return kept.length ? base + '?' + kept.join('&') : base;
}

return $input.all().map(function (item) {
  const j = item.json;
  const title = String(j.title || '').trim();
  const sourceUrl = cleanUrl(j.url);
  const description = htmlToText(j.description).slice(0, MAX_DESC);

  let postedAt = null;
  if (j.publication_date) {
    const d = new Date(j.publication_date + 'Z');
    if (!isNaN(d.getTime()) && d.getTime() <= Date.now() + 86400000) {
      postedAt = d.toISOString();
    }
  }

  let reason = null;
  if (!title) reason = 'empty title';
  else if (!/^https:\/\/[^\s]+$/.test(sourceUrl)) reason = 'invalid url';
  else if (description.length < 50) reason = 'description too short';

  return {
    json: {
      valid: reason === null,
      reason: reason,
      source: 'remotive',
      external_id: String(j.id === undefined || j.id === null ? '' : j.id),
      source_url: sourceUrl,
      title: title,
      company: j.company_name ? String(j.company_name).trim() : null,
      location: j.candidate_required_location || null,
      work_mode: 'remote',
      employment_type: j.job_type || null,
      description: description,
      posted_at: postedAt,
      raw: reason === null ? null : j
    }
  };
});

const all = $('normalize and validate').all().map(function (i) { return i.json; });
const fetched = all.length;
const rejected = all.filter(function (j) { return !j.valid; }).length;
const validCount = fetched - rejected;
const inserted = $input.all().filter(function (i) {
  return i.json.id !== undefined && i.json.id !== null;
}).length;
const duplicates = validCount - inserted;

return [{
  json: {
    workflow_name: '01-remotive-ingestion',
    status: 'success',
    fetched: fetched,
    rejected: rejected,
    duplicates: duplicates,
    inserted: inserted
  }
}];
